int remover25(const string& s) {
    int n=s.size(),ans=n;
    for(string fim:{"00","25","50","75"}){
        int j=n-1; while(j>=0 && s[j]!=fim[1]) --j;
        if(j<0) continue;
        int i=j-1; while(i>=0 && s[i]!=fim[0]) --i;
        if(i>=0) ans=min(ans,n-i-2);
    }
    return ans;
}
